import * as THREE from 'three';
import type { WorldContext } from '../../core/types';
import type { Handedness } from '../../core/XRInput';
import { TextPlane } from '../../ui/TextPlane';
import { FurnishedWorld } from '../grid/FurnishedWorld';
import type { GridPlan } from '../grid/gridPlan';
import { clearPlanWalls } from '../grid/shelfWalls';
import type { PlanSolid, PlanSolidKind } from '../grid/solids';
import { canLoadModels } from '../../core/chefFit';
import { PLAN_FLOOR_T } from '../editor/levelPlan';
import type { PlateTile } from '../shared/plateField';
import {
  plateTop,
  skinsOf,
  SPIKES_LIFT,
  SPIKES_MODEL,
  SPIKES_MODEL_TIPS,
} from '../test/zones/navigation';
import { HAZARD_FIRE } from '../nav/navProfile';
import type { NavGraph } from '../nav/navGraph';
import { NO_TILE, tileKey } from '../nav/navTile';
import { cellKey } from '../nav/cellGrid';
import type { Npc } from '../npc/Npc';
import { npcSkin } from '../npc/npcKinds';
import { createSky } from '../shared/environment';
import { BUTTON_DOME_R, buildRedButton, type RedButton } from '../shared/redButton';
import {
  dropCells,
  LAVA,
  NAV_TESTS,
  OBSTACLE_MODEL,
  gateDir,
  gateTile,
  inLava,
  lavaSpots,
  SPAWN,
  navTestPlan,
  navTestPlate,
  navTestWalls,
  tileCentre,
  type NavSpot,
  type NavTest,
} from './navTestPlan';

/**
 * Die Farben von Start und Ziel: grün und blau — gewünscht so. Die Platten
 * selbst sind die Küchenfliesen in denselben Farben (`navTestPlan.navTestPlate`);
 * die Farbe hier trägt nur noch die Tafel über dem Ziel.
 */
export const GOAL_COLOUR = 0x3b82f6;
const LAVA_COLOUR = 0xff5a1f;

/** Wie viel Leben die Lava je Sekunde nimmt — die Übungspuppe hat 160. */
const LAVA_DAMAGE = 400;

/** Wie nah er an die Mitte der Zielplatte herangeht, in Metern. */
const GOAL_REACH = 0.3;

/** So nah an der Mitte der Zielplatte gilt ein Test als bestanden, in Metern. */
const ARRIVED = 0.6;

/** Aus welcher Höhe die Arbeitsplatte fällt, in Metern über dem Boden. */
const DROP_HEIGHT = 1.6;
/** Wie schnell sie fällt, in m/s² — etwas langsamer als die Wirklichkeit, damit man es sieht. */
const DROP_GRAVITY = 6;

/** Was zu einem Test in der Welt gehört: der Knopf und wer gerade läuft. */
interface Bench {
  readonly test: NavTest;
  readonly button: RedButton;
  runner: Npc | null;
  arrived: boolean;
  /** Ob das Hindernis dieses Laufs schon liegt (`NavTest.drop`). */
  dropped: boolean;
  /** Die Arbeitsplatte, sobald sie da ist — und wie schnell sie gerade fällt. */
  obstacle: { model: THREE.Object3D; floor: number; speed: number } | null;
}

/**
 * **Test Navigation** — die Welt im Ordner _Test_ (`worlds/index.WORLD_FOLDERS`).
 *
 * Sechs Kammern aus Fensterwänden (`navTestPlan.ts`), vor jeder ein roter Knopf: Er
 * stellt eine Übungspuppe auf die grüne Platte und schickt sie zur blauen.
 * **Der berechnete Weg ist immer zu sehen** — die Ebene _Wege_ der
 * Navigationsansicht ist hier von Anfang an an (`setNavLayer('paths')`), und
 * die Linie folgt dem Weg, den der NPC gerade geplant hat. Die Lava tötet,
 * wer auf ihr steht (`burn`); geplant wird um sie herum, weil sie im Graphen
 * steht (`TileFacts.hazard`).
 */
export class NavTestWorld extends FurnishedWorld {
  private readonly benches: Bench[] = [];
  private readonly shapes: THREE.BufferGeometry[] = [];
  private readonly skins: THREE.Material[] = [];
  private readonly panels: TextPlane[] = [];
  private readonly pointed: THREE.Object3D[] = [];
  /** Die gemalte Lava — sie steht, bis die Stachelfallen da sind (`fillSpikes`). */
  private lava: THREE.Mesh | null = null;
  /** Ob die Welt schon wieder weg ist, während die Fallen noch unterwegs waren. */
  private gone = false;
  /**
   * **Die Zellen, auf denen gerade ein Hindernis liegt** (`dropObstacle`) — für
   * das Zellgitter des Spielers und für den Weg der NPCs (`cellBlocked`).
   */
  private readonly droppedCells = new Set<string>();

  protected override worldId(): string {
    return 'test-navigation';
  }

  protected override editorTitle(): string {
    return 'Test Navigation';
  }

  /**
   * Der Plan **ohne feste Wände und Schrägen** — die stehen als Stücke aus dem
   * Regal (`buildProps`, `navTestWalls`), wie in Sandbox und Haunting.
   */
  protected override layout(): GridPlan {
    const plan = navTestPlan();
    clearPlanWalls(plan);
    return plan;
  }

  /** Ein gespeicherter Umbau genauso: Wände nur aus dem Regal. */
  protected override planLoaded(plan: GridPlan): void {
    clearPlanWalls(plan);
  }

  /** Hier steht nichts außerhalb des Plans — die NPCs planen auf ihm (`GridWorld.navFromPlan`). */
  protected override navFromPlan(): boolean {
    return true;
  }

  /**
   * **Durch die Tore kommt nur der Spieler.** Gewünscht: _„zu allen Bereichen
   * auch ein Tor … über welches nur der Spieler rein und raus kann"_. Für das
   * Zellgitter des Spielers ist ein Durchgang aus dem Regal offen
   * (`gridSnap.wallCells` mit `MODEL_ARCHES`); im Graphen der NPCs steht an
   * derselben Kante eine Wand, also plant keiner hindurch — die Puppe bleibt
   * in ihrer Kammer.
   */
  protected override navReady(baked: NavGraph): void {
    super.navReady(baked);
    const graph = this.nav;
    if (!graph) return;
    for (const test of NAV_TESTS) graph.setWall(gateTile(test), gateDir(test), { kind: 'solid' });
    // Ein Hindernis, das schon liegt, liegt auch im neu gebackenen Graphen.
    for (const bench of this.benches)
      if (bench.dropped && bench.test.drop)
        graph.setBlocked(tileKey(bench.test.drop.x, bench.test.drop.z, 0), true);
  }

  /** Was hier auf Zellen steht, ist das gefallene Hindernis (`dropObstacle`). */
  protected override cellBlocked(ix: number, iz: number, level: number): boolean {
    return this.droppedCells.size > 0 && this.droppedCells.has(cellKey(ix, iz, level));
  }

  protected override skyColor(): number {
    return 0x9cc4e8;
  }

  protected override welcome(): string {
    return 'Test Navigation · roter Knopf startet den Test · grün Start, blau Ziel';
  }

  /** Leere Hände: Hier sieht man zu. */
  protected override beltLoadout(): ReadonlyArray<readonly [string, Handedness]> {
    return [];
  }

  protected override tint(): Partial<Record<PlanSolidKind, number>> {
    return { floor: 0x8a93a6 };
  }

  /**
   * **Der Boden kommt aus dem Regal** (`navTestPlan.navTestPlate`): überall der
   * Prototyp-Boden, auf Start und Ziel die grüne und die blaue Küchenfliese,
   * und auf der Lava gar keine — dort liegen die Stacheln (`fillSpikes`).
   */
  protected override floorPlate(tile: PlateTile): string | null {
    return navTestPlate(tile);
  }

  /**
   * **Unter den Stacheln wird kein Quader gezeichnet** — sie sind dort der
   * Boden. Ohne WebGL kommen sie nicht, und dann bleibt der Quader.
   */
  protected override underOwnFloor(solid: PlanSolid): boolean {
    if (!canLoadModels() || solid.kind !== 'floor') return false;
    return inLava(Math.floor(solid.x), Math.floor(solid.z), solid.level ?? 0);
  }

  protected override spawnPoint(): THREE.Vector3 {
    return new THREE.Vector3(SPAWN.x, 0, SPAWN.z);
  }

  protected override spawnYaw(): number {
    return 0;
  }

  protected override buildEnvironment(): void {
    super.buildEnvironment();
    this.root.add(createSky(0x6ea8e8, 0xdbe7f2));
  }

  /** **Wände, Platten, Lava, Knöpfe** — und die Wege von Anfang an sichtbar. */
  protected override buildProps(): void {
    const ctx = this.context;
    const plan = this.grid;
    if (!ctx || !plan) return;
    this.setNavLayer('paths', true);
    // **Die Wände aus dem Regal**, eingerastet wie aus der Hand: für das
    // Zellgitter und die NPCs Wände und Schrägen (`GridWorld.collectWalls`).
    // Steht schon ein Stück an seiner Stelle, kommt kein zweites (`placeModel`).
    for (const wall of navTestWalls())
      void this.placeModel(wall.path, new THREE.Vector3(wall.x, wall.y, wall.z), wall.yaw);
    this.paintLava(plan);
    this.fillSpikes(plan);
    for (const test of NAV_TESTS) {
      this.label(plan, test.goal, 'Ziel', test.title);
      this.benches.push(this.buildButton(ctx, test));
    }
    // Die Arbeitsplatte schon einmal holen, damit sie im Moment des Fallens da
    // ist und nicht erst über die Leitung kommt (`kaykitModel` merkt sich die
    // Vorlage).
    if (canLoadModels() && NAV_TESTS.some((test) => test.drop))
      void import('../../core/kaykitModel').then(async (module) => {
        const copy = await module.kaykitModel(OBSTACLE_MODEL);
        if (copy) for (const skin of skinsOf(copy)) skin.dispose();
      });
  }

  override update(dt: number, ctx: WorldContext): void {
    super.update(dt, ctx);
    for (const bench of this.benches) {
      bench.button.update(dt);
      this.watch(bench);
      this.watchDrop(bench);
      this.fall(bench, dt);
    }
    this.burn(dt);
  }

  override dispose(ctx: WorldContext): void {
    this.gone = true;
    this.lava = null;
    for (const object of this.pointed) ctx.pointer.remove(object);
    for (const bench of this.benches) {
      bench.button.dispose();
      this.clearObstacle(bench);
    }
    for (const panel of this.panels) panel.dispose();
    for (const shape of this.shapes) shape.dispose();
    for (const skin of this.skins) skin.dispose();
    this.benches.length = 0;
    this.pointed.length = 0;
    this.panels.length = 0;
    this.shapes.length = 0;
    this.skins.length = 0;
    super.dispose(ctx);
  }

  /** Eine Tafel über dem Ziel, die die Kamera ansieht. */
  private label(plan: GridPlan, at: NavSpot, title: string, body: string): void {
    const panel = new TextPlane({
      width: 1.3,
      height: 0.5,
      title,
      body,
      accent: GOAL_COLOUR,
      face: true,
    });
    panel.position.set(tileCentre(at.x), plan.graph.levelY(at.level) + 1.9, tileCentre(at.z));
    this.root.add(panel);
    this.panels.push(panel);
  }

  /** Die Lava: eine glühende Fläche über den Kacheln, die sie im Graphen trägt. */
  private paintLava(plan: GridPlan): void {
    const shape = new THREE.PlaneGeometry(LAVA.w, LAVA.d).rotateX(-Math.PI / 2);
    const skin = new THREE.MeshBasicMaterial({ color: LAVA_COLOUR });
    this.shapes.push(shape);
    this.skins.push(skin);
    const mesh = new THREE.Mesh(shape, skin);
    mesh.position.set(
      LAVA.x + LAVA.w / 2,
      plan.graph.levelY(LAVA.level) + 0.01,
      LAVA.z + LAVA.d / 2,
    );
    mesh.name = 'nav-test-lava';
    this.root.add(mesh);
    this.lava = mesh;
  }

  /**
   * **Die Lava sind Stacheln** — die rote Falle aus dem Regal, eine je Kachel,
   * dieselbe wie im Stachelfeld der Sandbox (`test/zones/navigation.ts`).
   *
   * Eingelassen wie dort: Die Oberseite ihrer Platte liegt fünf Millimeter
   * über dem Boden, zu sehen sind die Stacheln. Die Lava liegt aber oben auf
   * dem Podest, und dessen Boden ist nur `PLAN_FLOOR_T` dick — eine Falle in
   * voller Höhe hinge unten aus der Decke heraus. Also wird sie so weit
   * gestaucht, dass sie im Boden bleibt. Bis sie da ist, steht die gemalte
   * Lava; kommt sie nicht, bleibt die gemalte.
   */
  private fillSpikes(plan: GridPlan): void {
    if (!canLoadModels()) return;
    const floor = plan.graph.levelY(LAVA.level);
    void import('../../core/kaykitModel').then(async (module) => {
      const spots = lavaSpots();
      const copies = await Promise.all(spots.map(() => module.kaykitModel(SPIKES_MODEL)));
      const models = copies.filter((copy): copy is THREE.Object3D => copy !== null);
      const first = models[0];
      const top =
        models.length === spots.length && first ? plateTop(first, SPIKES_MODEL_TIPS) : null;
      if (this.gone || top === null || !first) {
        for (const model of models) for (const skin of skinsOf(model)) skin.dispose();
        return;
      }
      first.updateMatrixWorld(true);
      const bottom = new THREE.Box3().setFromObject(first).min.y;
      const squash = Math.min(1, (PLAN_FLOOR_T - 0.02) / Math.max(1e-6, top - bottom));
      const field = new THREE.Group();
      field.name = 'nav-test-spikes';
      field.position.y = floor + SPIKES_LIFT - top * squash;
      spots.forEach((spot, index) => {
        const model = models[index]!;
        model.position.set(spot.x, 0, spot.z);
        model.scale.y *= squash;
        field.add(model);
        for (const skin of skinsOf(model)) this.skins.push(skin);
      });
      this.root.add(field);
      this.lava?.removeFromParent();
      this.lava = null;
    });
  }

  /** Der rote Knopf vor einer Kammer. */
  private buildButton(ctx: WorldContext, test: NavTest): Bench {
    const button = buildRedButton({ title: test.title, body: test.body });
    button.group.position.set(tileCentre(test.button.x), 0, tileCentre(test.button.z));
    // Die Säule sieht nach Süden, dorthin, wo man herkommt.
    button.group.rotation.y = Math.PI;
    this.root.add(button.group);
    const bench: Bench = {
      test,
      button,
      runner: null,
      arrived: false,
      dropped: false,
      obstacle: null,
    };
    const run = (): boolean => this.run(bench);
    this.addUsable(
      button.dome,
      { use: run, usePrompt: () => `${test.title} starten` },
      { radius: 0.5, shot: BUTTON_DOME_R, half: 0.3 },
    );
    ctx.pointer.add({ object: button.dome, onSelect: run });
    this.pointed.push(button.dome);
    return bench;
  }

  /**
   * **Einen Test starten**: den letzten Läufer wegräumen, eine Übungspuppe
   * auf die grüne Platte stellen und zur blauen schicken.
   */
  private run(bench: Bench): boolean {
    const director = this.director;
    const plan = this.grid;
    if (!director || !plan) return false;
    bench.button.press();
    if (bench.runner) director.remove(bench.runner);
    // Das Hindernis des letzten Laufs räumt der nächste weg: Er beginnt mit
    // freiem Weg, sonst gäbe es nichts neu zu planen.
    this.clearObstacle(bench);
    const { start, goal } = bench.test;
    const from = new THREE.Vector3(
      tileCentre(start.x),
      plan.graph.levelY(start.level),
      tileCentre(start.z),
    );
    const to = new THREE.Vector3(
      tileCentre(goal.x),
      plan.graph.levelY(goal.level),
      tileCentre(goal.z),
    );
    bench.runner = director.spawn({
      kind: 'dummy',
      brain: 'errand',
      at: from,
      errand: to,
      yaw: Math.atan2(-(to.x - from.x), -(to.z - from.z)),
      speed: npcSkin('dummy').speed,
    });
    bench.arrived = false;
    if (!bench.runner) return false;
    // Bis auf die Platte und nicht nur in ihre Nähe (`npcBrain.ERRAND_REACH`
    // sind 1,25 m) — der Test ist bestanden, wenn er auf ihr steht.
    bench.runner.sendTo(to, GOAL_REACH);
    this.announce(`${bench.test.title}: los`);
    return true;
  }

  /** Ist er angekommen? Einmal melden. */
  private watch(bench: Bench): void {
    const runner = bench.runner;
    if (!runner || bench.arrived || !runner.alive) return;
    const plan = this.grid;
    if (!plan) return;
    const feet = runner.feet(_feet);
    const goal = bench.test.goal;
    const near =
      Math.hypot(feet.x - tileCentre(goal.x), feet.z - tileCentre(goal.z)) < ARRIVED &&
      Math.abs(feet.y - plan.graph.levelY(goal.level)) < 1;
    if (!near) return;
    bench.arrived = true;
    this.announce(`${bench.test.title}: am Ziel`);
  }

  /**
   * **Ist er weit genug, fällt ihm das Hindernis in den Weg** (`NavTest.drop`):
   * sobald er die Reihe `trigger` hinter sich hat — da ist sein Weg längst
   * geradeaus geplant.
   */
  private watchDrop(bench: Bench): void {
    const drop = bench.test.drop;
    const runner = bench.runner;
    if (!drop || bench.dropped || !runner || !runner.alive) return;
    if (runner.feet(_feet).z > drop.trigger) return;
    this.dropObstacle(bench);
  }

  /**
   * **Die Arbeitsplatte fallen lassen** — und die Kachel sofort sperren.
   *
   * Gesperrt wird zweimal, weil der NPC zweimal plant (`navAgent.plan`): grob
   * über Kacheln (`NavGraph.setBlocked` — eine gesperrte Kachel, von der er
   * keine eigene Meinung hat, hält er für gesperrt, `navBelief`) und fein über
   * Zellen (`cellBlocked`, zwei mal zwei unter der Platte). Neu geplant wird
   * beim nächsten regelmäßigen Nachplanen (`NavAgent` `replan`), also nach
   * spätestens einer guten halben Sekunde — und die Linie des Wegs knickt
   * sichtbar um die Platte herum.
   *
   * Das Bild kommt aus dem Regal (`OBSTACLE_MODEL`); ohne WebGL kommt keins,
   * gesperrt ist trotzdem.
   */
  private dropObstacle(bench: Bench): void {
    const drop = bench.test.drop;
    const plan = this.grid;
    if (!drop || !plan) return;
    bench.dropped = true;
    for (const cell of dropCells(drop)) this.droppedCells.add(cell);
    this.nav?.setBlocked(tileKey(drop.x, drop.z, 0), true);
    this.announce(`${bench.test.title}: Arbeitsplatte im Weg`);
    if (!canLoadModels()) return;
    const floor = plan.graph.levelY(0);
    void import('../../core/kaykitModel').then(async (module) => {
      const model = await module.kaykitModel(OBSTACLE_MODEL);
      if (!model) return;
      // Inzwischen abgeräumt oder schon der nächste Lauf: Dann gehört sie
      // niemandem mehr.
      if (this.gone || !bench.dropped || bench.obstacle) {
        for (const skin of skinsOf(model)) skin.dispose();
        return;
      }
      // Die Unterkante auf den Boden, die Mitte auf die Kachelmitte — gemessen
      // und nicht abgeschrieben.
      model.position.set(0, 0, 0);
      model.updateMatrixWorld(true);
      const box = new THREE.Box3().setFromObject(model);
      const centre = box.getCenter(new THREE.Vector3());
      const holder = new THREE.Group();
      holder.name = 'nav-test-hindernis';
      model.position.set(-centre.x, -box.min.y, -centre.z);
      holder.add(model);
      holder.position.set(tileCentre(drop.x), floor + DROP_HEIGHT, tileCentre(drop.z));
      this.root.add(holder);
      bench.obstacle = { model: holder, floor, speed: 0 };
    });
  }

  /** Sie fällt, bis sie auf dem Boden liegt. */
  private fall(bench: Bench, dt: number): void {
    const obstacle = bench.obstacle;
    if (!obstacle || obstacle.model.position.y <= obstacle.floor) return;
    obstacle.speed += DROP_GRAVITY * dt;
    obstacle.model.position.y = Math.max(
      obstacle.floor,
      obstacle.model.position.y - obstacle.speed * dt,
    );
  }

  /** Das Hindernis wegräumen und Kachel und Zellen wieder freigeben. */
  private clearObstacle(bench: Bench): void {
    const drop = bench.test.drop;
    if (drop && bench.dropped) {
      for (const cell of dropCells(drop)) this.droppedCells.delete(cell);
      this.nav?.setBlocked(tileKey(drop.x, drop.z, 0), false);
    }
    bench.dropped = false;
    const obstacle = bench.obstacle;
    bench.obstacle = null;
    if (!obstacle) return;
    obstacle.model.removeFromParent();
    for (const skin of skinsOf(obstacle.model)) skin.dispose();
  }

  /** **Die Lava tötet**, wer auf ihr steht (`NpcDirector.harm`). */
  private burn(dt: number): void {
    const graph = this.grid?.graph;
    if (!graph || !this.director) return;
    this.director.harm((feet) => {
      const key = graph.at(feet.x, feet.z, feet.y);
      if (key === NO_TILE) return 0;
      return (graph.tile(key)?.hazard ?? 0) & HAZARD_FIRE ? LAVA_DAMAGE * dt : 0;
    });
  }
}

const _feet = new THREE.Vector3();
